html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
{%- set p = altor_party(doc) -%}
{%- set vat = altor_item_taxes(doc) -%}
{%- set projects = [] -%}{%- for i in doc.get("items") if i.project and i.project not in projects %}{% set _ = projects.append(i.project) %}{% endfor -%}
<div class="ap">
{{ ap.header(c, "PURCHASE ORDER", "أمر شراء", [
    ["PO No.", doc.name],
    ["PO Date", ap.date(doc.transaction_date)],
    ["Required By", ap.date(doc.schedule_date)],
    ["Reference", doc.get("custom_reference")],
    ["Supplier Quotation", doc.get("supplier_quotation")]
]) }}
{%- set ship = altor_lines(doc.get("shipping_address_display")) %}
{{ ap.two_boxes(ap.party_box("Supplier", p), ap.info_box("Deliver To", [
    ["Address", ship | join("<br>") if ship else (c.address | join(", "))],
    ["Project", projects | join(", ")],
    ["Payment Terms", doc.get("payment_terms_template")],
    ["Incoterm", doc.get("incoterm")]
])) }}
<table class="items">
  <thead><tr>
    <th style="width:5%">#</th><th>Item &amp; Description</th><th style="width:7%">Unit</th><th class="right" style="width:7%">Qty</th>
    <th class="right" style="width:11%">Rate</th><th class="right" style="width:12%">Amount</th><th class="right" style="width:7%">VAT %</th>
    <th class="right" style="width:10%">VAT</th><th class="right" style="width:12%">Total ({{ doc.currency }})</th>
  </tr></thead>
  <tbody>
  {%- for item in doc.get("items") %}{% set t = vat[item.name] %}
  <tr><td>{{ loop.index }}</td><td><div class="item-name">{{ item.item_name }}</div><div class="muted">{{ item.item_code }}{% if item.schedule_date and item.schedule_date != doc.schedule_date %} &middot; by {{ ap.date(item.schedule_date) }}{% endif %}</div>{% if item.description and item.description | striptags | trim != item.item_name %}{{ ap.bullets(item.description) }}{% endif %}</td>
    <td>{{ item.uom }}</td><td class="right">{{ ap.num(item.qty) }}</td><td class="right">{{ ap.amt(item.rate) }}</td>
    <td class="right">{{ ap.amt(t.net) }}</td><td class="right">{{ t.rate }}%</td><td class="right">{{ ap.amt(t.amount) }}</td><td class="right"><b>{{ ap.amt(t.total) }}</b></td></tr>
  {%- endfor %}
  </tbody>
</table>
{{ ap.totals(doc) }}
{%- if doc.get("custom_delivery_instructions") %}<div class="sec"><div class="sec-title">Delivery Instructions</div>{{ ap.bullets(doc.custom_delivery_instructions) }}</div>{% endif %}
{{ ap.section("Payment Terms", ap.payment_terms(doc)) }}
{{ ap.section("Terms & Conditions", doc.get("terms")) }}
<p class="muted" style="margin-top:8px">Please quote the PO number on all delivery notes and invoices. Goods are subject to inspection on receipt.</p>
{{ ap.signatures(c, ["Prepared by", "Approved by", "Supplier Acceptance"], 1) }}
{{ ap.footer(c) }}
</div>
